/**
 * Register bundled block pattern categories and patterns.
 *
 * @since 0.8.0
 * @return void
 */
function variable_thema_register_block_patterns() {
	if ( ! function_exists( 'register_block_pattern' ) || ! function_exists( 'register_block_pattern_category' ) ) {
		return;
	}

	$category              = 'variable-thema-parts';
	$dummy_avatar_url      = esc_url( get_theme_file_uri( 'assets/images/dummy-avatar.svg' ) );
	$dummy_linkcard_url    = $dummy_avatar_url;
	$dummy_hero_url        = $dummy_avatar_url;
	$dummy_testimonial_url = $dummy_avatar_url;
	$dummy_profile_url     = $dummy_avatar_url;

	register_block_pattern_category(
		$category,
		array(
			'label' => __( 'variable Thema Parts', 'variable-thema' ),
		)
	);

	register_block_pattern(
		'variable-thema/homepage',
		array(
			'title'       => __( 'Front page', 'variable-thema' ),
			'description' => __( 'A front page layout composed of the bundled landing-page sections.', 'variable-thema' ),
